-- ===== stats.sql（使用面与功能盘点，sonnet 子代理编写）
##QZ_a_subj_usage
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjlev, LEFT(a.subjcode,1) AS firstch, CASE WHEN LEFT(a.subjcode,1) LIKE '[0-9]' THEN 'num' ELSE 'alpha' END AS kind, COUNT(*) AS total_cnt, SUM(CASE WHEN a.endflag='Y' THEN 1 ELSE 0 END) AS leaf_cnt, SUM(CASE WHEN ISNULL(a.sealflag,'N')='Y' THEN 1 ELSE 0 END) AS sealed_cnt, SUM(CASE WHEN a.endflag='Y' AND act.n>0 THEN 1 ELSE 0 END) AS leaf_active_cnt, SUM(CASE WHEN a.endflag='Y' AND ISNULL(act.n,0)=0 THEN 1 ELSE 0 END) AS leaf_idle_cnt, SUM(CASE WHEN ISNULL(a.endflag,'N')<>'Y' AND act.n>0 THEN 1 ELSE 0 END) AS nonleaf_posted_cnt FROM u8cloud_QZ.dbo.bd_accsubj a JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook LEFT JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, a.subjlev, LEFT(a.subjcode,1), CASE WHEN LEFT(a.subjcode,1) LIKE '[0-9]' THEN 'num' ELSE 'alpha' END ORDER BY 1, 3, 2
##SF_a_subj_usage
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjlev, LEFT(a.subjcode,1) AS firstch, CASE WHEN LEFT(a.subjcode,1) LIKE '[0-9]' THEN 'num' ELSE 'alpha' END AS kind, COUNT(*) AS total_cnt, SUM(CASE WHEN a.endflag='Y' THEN 1 ELSE 0 END) AS leaf_cnt, SUM(CASE WHEN ISNULL(a.sealflag,'N')='Y' THEN 1 ELSE 0 END) AS sealed_cnt, SUM(CASE WHEN a.endflag='Y' AND act.n>0 THEN 1 ELSE 0 END) AS leaf_active_cnt, SUM(CASE WHEN a.endflag='Y' AND ISNULL(act.n,0)=0 THEN 1 ELSE 0 END) AS leaf_idle_cnt, SUM(CASE WHEN ISNULL(a.endflag,'N')<>'Y' AND act.n>0 THEN 1 ELSE 0 END) AS nonleaf_posted_cnt FROM u8cloud.dbo.bd_accsubj a JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook LEFT JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, a.subjlev, LEFT(a.subjcode,1), CASE WHEN LEFT(a.subjcode,1) LIKE '[0-9]' THEN 'num' ELSE 'alpha' END ORDER BY 1, 3, 2
##QZ_b1_idle_leaf cap=20000
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjcode, a.subjname, a.subjlev, a.sealflag FROM u8cloud_QZ.dbo.bd_accsubj a JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook LEFT JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') AND a.endflag='Y' AND ISNULL(act.n,0)=0 ORDER BY 1, 2
##SF_b1_idle_leaf cap=20000
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjcode, a.subjname, a.subjlev, a.sealflag FROM u8cloud.dbo.bd_accsubj a JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook LEFT JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') AND a.endflag='Y' AND ISNULL(act.n,0)=0 ORDER BY 1, 2
##QZ_b2_active_leaf cap=20000
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjcode, a.subjname, a.endflag, act.n AS line_cnt FROM u8cloud_QZ.dbo.bd_accsubj a JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') ORDER BY 1, 2
##SF_b2_active_leaf cap=20000
WITH act AS (SELECT v.pk_glorgbook, d.pk_accsubj, COUNT(*) AS n FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' GROUP BY v.pk_glorgbook, d.pk_accsubj) SELECT ob.glorgbookcode, a.subjcode, a.subjname, a.endflag, act.n AS line_cnt FROM u8cloud.dbo.bd_accsubj a JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook JOIN act ON act.pk_accsubj=a.pk_accsubj AND act.pk_glorgbook=ob.pk_glorgbook WHERE ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') ORDER BY 1, 2
##QZ_c1_aux_by_dim
WITH win AS (SELECT v.pk_glorgbook, d.pk_accsubj, f.checktype, d.pk_detail, f.valuecode FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud_QZ.dbo.gl_freevalue f ON f.freevalueid=d.assid WHERE d.dr=0 AND ISNULL(f.dr,0)=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609'), use1 AS (SELECT pk_glorgbook, checktype, COUNT(DISTINCT pk_detail) AS lines, COUNT(DISTINCT valuecode) AS vals FROM win GROUP BY pk_glorgbook, checktype), use2 AS (SELECT DISTINCT pk_glorgbook, pk_accsubj, checktype FROM win), en AS (SELECT ob.glorgbookcode, ob.pk_glorgbook, a.pk_accsubj, s.pk_bdinfo FROM u8cloud_QZ.dbo.bd_subjass s JOIN u8cloud_QZ.dbo.bd_accsubj a ON a.pk_accsubj=s.pk_accsubj JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND a.endflag='Y' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001')) SELECT en.glorgbookcode, i.bdname, COUNT(DISTINCT en.pk_accsubj) AS enabled_leaf_cnt, ISNULL(MAX(u1.lines),0) AS used_line_cnt, ISNULL(MAX(u1.vals),0) AS used_value_cnt, COUNT(DISTINCT CASE WHEN u2.pk_accsubj IS NULL THEN en.pk_accsubj END) AS never_used_subj_cnt FROM en JOIN u8cloud_QZ.dbo.bd_bdinfo i ON i.pk_bdinfo=en.pk_bdinfo LEFT JOIN use1 u1 ON u1.pk_glorgbook=en.pk_glorgbook AND u1.checktype=en.pk_bdinfo LEFT JOIN use2 u2 ON u2.pk_glorgbook=en.pk_glorgbook AND u2.pk_accsubj=en.pk_accsubj AND u2.checktype=en.pk_bdinfo GROUP BY en.glorgbookcode, i.bdname ORDER BY 1, 2
##SF_c1_aux_by_dim
WITH win AS (SELECT v.pk_glorgbook, d.pk_accsubj, f.checktype, d.pk_detail, f.valuecode FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud.dbo.gl_freevalue f ON f.freevalueid=d.assid WHERE d.dr=0 AND ISNULL(f.dr,0)=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609'), use1 AS (SELECT pk_glorgbook, checktype, COUNT(DISTINCT pk_detail) AS lines, COUNT(DISTINCT valuecode) AS vals FROM win GROUP BY pk_glorgbook, checktype), use2 AS (SELECT DISTINCT pk_glorgbook, pk_accsubj, checktype FROM win), en AS (SELECT ob.glorgbookcode, ob.pk_glorgbook, a.pk_accsubj, s.pk_bdinfo FROM u8cloud.dbo.bd_subjass s JOIN u8cloud.dbo.bd_accsubj a ON a.pk_accsubj=s.pk_accsubj JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=a.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(a.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND a.endflag='Y' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001')) SELECT en.glorgbookcode, i.bdname, COUNT(DISTINCT en.pk_accsubj) AS enabled_leaf_cnt, ISNULL(MAX(u1.lines),0) AS used_line_cnt, ISNULL(MAX(u1.vals),0) AS used_value_cnt, COUNT(DISTINCT CASE WHEN u2.pk_accsubj IS NULL THEN en.pk_accsubj END) AS never_used_subj_cnt FROM en JOIN u8cloud.dbo.bd_bdinfo i ON i.pk_bdinfo=en.pk_bdinfo LEFT JOIN use1 u1 ON u1.pk_glorgbook=en.pk_glorgbook AND u1.checktype=en.pk_bdinfo LEFT JOIN use2 u2 ON u2.pk_glorgbook=en.pk_glorgbook AND u2.pk_accsubj=en.pk_accsubj AND u2.checktype=en.pk_bdinfo GROUP BY en.glorgbookcode, i.bdname ORDER BY 1, 2
##QZ_c2_aux_used_all
SELECT ob.glorgbookcode, i.bdname, COUNT(DISTINCT d.pk_detail) AS line_cnt, COUNT(DISTINCT f.valuecode) AS value_cnt, COUNT(DISTINCT d.pk_accsubj) AS subj_cnt FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook JOIN u8cloud_QZ.dbo.gl_freevalue f ON f.freevalueid=d.assid JOIN u8cloud_QZ.dbo.bd_bdinfo i ON i.pk_bdinfo=f.checktype WHERE d.dr=0 AND ISNULL(f.dr,0)=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, i.bdname ORDER BY 1, 2
##SF_c2_aux_used_all
SELECT ob.glorgbookcode, i.bdname, COUNT(DISTINCT d.pk_detail) AS line_cnt, COUNT(DISTINCT f.valuecode) AS value_cnt, COUNT(DISTINCT d.pk_accsubj) AS subj_cnt FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook JOIN u8cloud.dbo.gl_freevalue f ON f.freevalueid=d.assid JOIN u8cloud.dbo.bd_bdinfo i ON i.pk_bdinfo=f.checktype WHERE d.dr=0 AND ISNULL(f.dr,0)=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, i.bdname ORDER BY 1, 2
##QZ_d1_createcorp
SELECT s.pk_corp, c.unitcode, s.funccode, fr.fun_name, s.accountyear, s.accountmonth, s.settledyear, s.settledmonth FROM u8cloud_QZ.dbo.sm_createcorp s LEFT JOIN u8cloud_QZ.dbo.bd_corp c ON c.pk_corp=s.pk_corp LEFT JOIN (SELECT fun_code, MAX(fun_name) AS fun_name, MIN(fun_level) AS fun_level FROM u8cloud_QZ.dbo.sm_funcregister GROUP BY fun_code) fr ON fr.fun_code=s.funccode WHERE ISNULL(s.dr,0)=0 ORDER BY c.unitcode, s.funccode
##SF_d1_createcorp
SELECT s.pk_corp, c.unitcode, s.funccode, fr.fun_name, s.accountyear, s.accountmonth, s.settledyear, s.settledmonth FROM u8cloud.dbo.sm_createcorp s LEFT JOIN u8cloud.dbo.bd_corp c ON c.pk_corp=s.pk_corp LEFT JOIN (SELECT fun_code, MAX(fun_name) AS fun_name, MIN(fun_level) AS fun_level FROM u8cloud.dbo.sm_funcregister GROUP BY fun_code) fr ON fr.fun_code=s.funccode WHERE ISNULL(s.dr,0)=0 ORDER BY c.unitcode, s.funccode
