##QZ_d3_oplog_by_func
SELECT TOP 300 o.enterfunctioncode, MAX(o.entersystem) AS entersystem, MAX(o.enterfunction) AS enterfunction, MAX(fr.fun_name) AS fun_name, MAX(fr.fun_level) AS fun_level, LEN(o.enterfunctioncode) AS fun_code_len, COUNT(*) AS ops, COUNT(DISTINCT o.operatorid) AS users, MIN(LEFT(o.logintime,10)) AS first_day, MAX(LEFT(o.logintime,10)) AS last_day FROM u8cloud_QZ.dbo.sm_operatelog o LEFT JOIN (SELECT fun_code, MAX(fun_name) AS fun_name, MIN(fun_level) AS fun_level FROM u8cloud_QZ.dbo.sm_funcregister GROUP BY fun_code) fr ON fr.fun_code=o.enterfunctioncode WHERE ISNULL(o.dr,0)=0 AND LEFT(o.logintime,10) BETWEEN '2025-10-01' AND '2026-09-30' GROUP BY o.enterfunctioncode ORDER BY COUNT(*) DESC
##SF_d3_oplog_by_func
SELECT TOP 300 o.enterfunctioncode, MAX(o.entersystem) AS entersystem, MAX(o.enterfunction) AS enterfunction, MAX(fr.fun_name) AS fun_name, MAX(fr.fun_level) AS fun_level, LEN(o.enterfunctioncode) AS fun_code_len, COUNT(*) AS ops, COUNT(DISTINCT o.operatorid) AS users, MIN(LEFT(o.logintime,10)) AS first_day, MAX(LEFT(o.logintime,10)) AS last_day FROM u8cloud.dbo.sm_operatelog o LEFT JOIN (SELECT fun_code, MAX(fun_name) AS fun_name, MIN(fun_level) AS fun_level FROM u8cloud.dbo.sm_funcregister GROUP BY fun_code) fr ON fr.fun_code=o.enterfunctioncode WHERE ISNULL(o.dr,0)=0 AND LEFT(o.logintime,10) BETWEEN '2025-10-01' AND '2026-09-30' GROUP BY o.enterfunctioncode ORDER BY COUNT(*) DESC
##QZ_d4_oplog_by_system
SELECT o.entersystem, LEFT(o.enterfunctioncode,2) AS fun_prefix2, COUNT(*) AS ops, COUNT(DISTINCT o.operatorid) AS users, COUNT(DISTINCT o.enterfunctioncode) AS func_cnt FROM u8cloud_QZ.dbo.sm_operatelog o WHERE ISNULL(o.dr,0)=0 AND LEFT(o.logintime,10) BETWEEN '2025-10-01' AND '2026-09-30' GROUP BY o.entersystem, LEFT(o.enterfunctioncode,2) ORDER BY 3 DESC
##SF_d4_oplog_by_system
SELECT o.entersystem, LEFT(o.enterfunctioncode,2) AS fun_prefix2, COUNT(*) AS ops, COUNT(DISTINCT o.operatorid) AS users, COUNT(DISTINCT o.enterfunctioncode) AS func_cnt FROM u8cloud.dbo.sm_operatelog o WHERE ISNULL(o.dr,0)=0 AND LEFT(o.logintime,10) BETWEEN '2025-10-01' AND '2026-09-30' GROUP BY o.entersystem, LEFT(o.enterfunctioncode,2) ORDER BY 3 DESC
