##QZ_e1_roles
SELECT r.role_code, r.role_name, r.pk_corp, c.unitcode, r.usercount, r.resource_type, (SELECT COUNT(*) FROM u8cloud_QZ.dbo.sm_user_role ur WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0) AS role_user_rows, (SELECT COUNT(DISTINCT ur.cuserid) FROM u8cloud_QZ.dbo.sm_user_role ur WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0) AS role_user_distinct, (SELECT COUNT(DISTINCT ur.cuserid) FROM u8cloud_QZ.dbo.sm_user_role ur JOIN u8cloud_QZ.dbo.sm_user u ON u.cuserid=ur.cuserid WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0 AND ISNULL(u.dr,0)=0 AND ISNULL(u.locked_tag,'N')<>'Y' AND ISNULL(u.disable_time,'')='') AS role_user_effective, (SELECT COUNT(DISTINCT p.resource_data_id) FROM u8cloud_QZ.dbo.sm_power_func p WHERE p.pk_role=r.pk_role AND ISNULL(p.dr,0)=0) AS power_func_nodes, (SELECT COUNT(*) FROM u8cloud_QZ.dbo.sm_power_butn b WHERE b.pk_role=r.pk_role AND ISNULL(b.dr,0)=0) AS power_butn_cnt FROM u8cloud_QZ.dbo.sm_role r LEFT JOIN u8cloud_QZ.dbo.bd_corp c ON c.pk_corp=r.pk_corp WHERE ISNULL(r.dr,0)=0 ORDER BY r.role_code
##SF_e1_roles
SELECT r.role_code, r.role_name, r.pk_corp, c.unitcode, r.usercount, r.resource_type, (SELECT COUNT(*) FROM u8cloud.dbo.sm_user_role ur WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0) AS role_user_rows, (SELECT COUNT(DISTINCT ur.cuserid) FROM u8cloud.dbo.sm_user_role ur WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0) AS role_user_distinct, (SELECT COUNT(DISTINCT ur.cuserid) FROM u8cloud.dbo.sm_user_role ur JOIN u8cloud.dbo.sm_user u ON u.cuserid=ur.cuserid WHERE ur.pk_role=r.pk_role AND ISNULL(ur.dr,0)=0 AND ISNULL(u.dr,0)=0 AND ISNULL(u.locked_tag,'N')<>'Y' AND ISNULL(u.disable_time,'')='') AS role_user_effective, (SELECT COUNT(DISTINCT p.resource_data_id) FROM u8cloud.dbo.sm_power_func p WHERE p.pk_role=r.pk_role AND ISNULL(p.dr,0)=0) AS power_func_nodes, (SELECT COUNT(*) FROM u8cloud.dbo.sm_power_butn b WHERE b.pk_role=r.pk_role AND ISNULL(b.dr,0)=0) AS power_butn_cnt FROM u8cloud.dbo.sm_role r LEFT JOIN u8cloud.dbo.bd_corp c ON c.pk_corp=r.pk_corp WHERE ISNULL(r.dr,0)=0 ORDER BY r.role_code
##QZ_e2_role_func_cat
SELECT r.role_code, COUNT(DISTINCT f.cfunid) AS total_nodes, SUM(CASE WHEN f.fun_name LIKE N'%凭证%' THEN 1 ELSE 0 END) AS n_voucher, SUM(CASE WHEN f.fun_name LIKE N'%审核%' THEN 1 ELSE 0 END) AS n_audit, SUM(CASE WHEN f.fun_name LIKE N'%记账%' THEN 1 ELSE 0 END) AS n_post, SUM(CASE WHEN f.fun_name LIKE N'%结账%' OR f.fun_name LIKE N'%年结%' THEN 1 ELSE 0 END) AS n_settle, SUM(CASE WHEN f.fun_name LIKE N'%出纳%' OR f.fun_name LIKE N'%签字%' THEN 1 ELSE 0 END) AS n_cashier, SUM(CASE WHEN f.fun_name LIKE N'%余额%' OR f.fun_name LIKE N'%明细账%' THEN 1 ELSE 0 END) AS n_balance, SUM(CASE WHEN f.fun_name LIKE N'%报表%' THEN 1 ELSE 0 END) AS n_report, SUM(CASE WHEN f.fun_name LIKE N'%核销%' THEN 1 ELSE 0 END) AS n_verify, SUM(CASE WHEN f.fun_name LIKE N'%期初%' THEN 1 ELSE 0 END) AS n_init, SUM(CASE WHEN f.fun_name LIKE N'%打印%' THEN 1 ELSE 0 END) AS n_print, SUM(CASE WHEN f.fun_name LIKE N'%权限%' OR f.fun_name LIKE N'%用户%' THEN 1 ELSE 0 END) AS n_perm, SUM(CASE WHEN f.fun_name LIKE N'%固定资产%' THEN 1 ELSE 0 END) AS n_fa, SUM(CASE WHEN f.fun_name LIKE N'%往来%' THEN 1 ELSE 0 END) AS n_arap, SUM(CASE WHEN f.fun_name LIKE N'%系统管理%' THEN 1 ELSE 0 END) AS n_sysadmin FROM u8cloud_QZ.dbo.sm_role r JOIN u8cloud_QZ.dbo.sm_power_func p ON p.pk_role=r.pk_role AND ISNULL(p.dr,0)=0 JOIN u8cloud_QZ.dbo.sm_funcregister f ON f.cfunid=p.resource_data_id WHERE ISNULL(r.dr,0)=0 GROUP BY r.role_code ORDER BY 1
##SF_e2_role_func_cat
SELECT r.role_code, COUNT(DISTINCT f.cfunid) AS total_nodes, SUM(CASE WHEN f.fun_name LIKE N'%凭证%' THEN 1 ELSE 0 END) AS n_voucher, SUM(CASE WHEN f.fun_name LIKE N'%审核%' THEN 1 ELSE 0 END) AS n_audit, SUM(CASE WHEN f.fun_name LIKE N'%记账%' THEN 1 ELSE 0 END) AS n_post, SUM(CASE WHEN f.fun_name LIKE N'%结账%' OR f.fun_name LIKE N'%年结%' THEN 1 ELSE 0 END) AS n_settle, SUM(CASE WHEN f.fun_name LIKE N'%出纳%' OR f.fun_name LIKE N'%签字%' THEN 1 ELSE 0 END) AS n_cashier, SUM(CASE WHEN f.fun_name LIKE N'%余额%' OR f.fun_name LIKE N'%明细账%' THEN 1 ELSE 0 END) AS n_balance, SUM(CASE WHEN f.fun_name LIKE N'%报表%' THEN 1 ELSE 0 END) AS n_report, SUM(CASE WHEN f.fun_name LIKE N'%核销%' THEN 1 ELSE 0 END) AS n_verify, SUM(CASE WHEN f.fun_name LIKE N'%期初%' THEN 1 ELSE 0 END) AS n_init, SUM(CASE WHEN f.fun_name LIKE N'%打印%' THEN 1 ELSE 0 END) AS n_print, SUM(CASE WHEN f.fun_name LIKE N'%权限%' OR f.fun_name LIKE N'%用户%' THEN 1 ELSE 0 END) AS n_perm, SUM(CASE WHEN f.fun_name LIKE N'%固定资产%' THEN 1 ELSE 0 END) AS n_fa, SUM(CASE WHEN f.fun_name LIKE N'%往来%' THEN 1 ELSE 0 END) AS n_arap, SUM(CASE WHEN f.fun_name LIKE N'%系统管理%' THEN 1 ELSE 0 END) AS n_sysadmin FROM u8cloud.dbo.sm_role r JOIN u8cloud.dbo.sm_power_func p ON p.pk_role=r.pk_role AND ISNULL(p.dr,0)=0 JOIN u8cloud.dbo.sm_funcregister f ON f.cfunid=p.resource_data_id WHERE ISNULL(r.dr,0)=0 GROUP BY r.role_code ORDER BY 1
##QZ_e3_role_func_detail cap=20000
SELECT DISTINCT r.role_code, f.fun_code, f.fun_name, f.fun_level, LEFT(f.fun_code,4) AS fun_code_prefix4 FROM u8cloud_QZ.dbo.sm_role r JOIN u8cloud_QZ.dbo.sm_power_func p ON p.pk_role=r.pk_role AND ISNULL(p.dr,0)=0 JOIN u8cloud_QZ.dbo.sm_funcregister f ON f.cfunid=p.resource_data_id WHERE ISNULL(r.dr,0)=0 AND (f.fun_name LIKE N'%凭证%' OR f.fun_name LIKE N'%审核%' OR f.fun_name LIKE N'%记账%' OR f.fun_name LIKE N'%结账%' OR f.fun_name LIKE N'%出纳%' OR f.fun_name LIKE N'%签字%' OR f.fun_name LIKE N'%余额%' OR f.fun_name LIKE N'%明细账%' OR f.fun_name LIKE N'%报表%' OR f.fun_name LIKE N'%核销%' OR f.fun_name LIKE N'%期初%' OR f.fun_name LIKE N'%年结%' OR f.fun_name LIKE N'%打印%' OR f.fun_name LIKE N'%权限%' OR f.fun_name LIKE N'%用户%' OR f.fun_name LIKE N'%总账%' OR f.fun_name LIKE N'%固定资产%' OR f.fun_name LIKE N'%往来%' OR f.fun_name LIKE N'%系统管理%' OR f.fun_name LIKE N'%现金流量%') ORDER BY 1, 2
