##QZ_e8_users
SELECT CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END AS sys_account, ISNULL(u.locked_tag,'N') AS locked_tag, CASE WHEN ISNULL(u.disable_time,'')='' THEN 'none' WHEN LEFT(u.disable_time,10)<='2026-10-14' THEN 'disabled' ELSE 'future' END AS disable_state, CASE WHEN ISNULL(u.able_time,'')='' THEN 'none' WHEN LEFT(u.able_time,10)<='2026-10-14' THEN 'enabled' ELSE 'notyet' END AS able_state, ISNULL(u.authen_type,'') AS authen_type, CASE WHEN EXISTS (SELECT 1 FROM u8cloud_QZ.dbo.sm_user_role ur WHERE ur.cuserid=u.cuserid AND ISNULL(ur.dr,0)=0) THEN 'Y' ELSE 'N' END AS has_role, COUNT(*) AS user_cnt FROM u8cloud_QZ.dbo.sm_user u WHERE ISNULL(u.dr,0)=0 GROUP BY CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END, ISNULL(u.locked_tag,'N'), CASE WHEN ISNULL(u.disable_time,'')='' THEN 'none' WHEN LEFT(u.disable_time,10)<='2026-10-14' THEN 'disabled' ELSE 'future' END, CASE WHEN ISNULL(u.able_time,'')='' THEN 'none' WHEN LEFT(u.able_time,10)<='2026-10-14' THEN 'enabled' ELSE 'notyet' END, ISNULL(u.authen_type,''), CASE WHEN EXISTS (SELECT 1 FROM u8cloud_QZ.dbo.sm_user_role ur WHERE ur.cuserid=u.cuserid AND ISNULL(ur.dr,0)=0) THEN 'Y' ELSE 'N' END ORDER BY 1, 2, 3, 4
##SF_e8_users
SELECT CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END AS sys_account, ISNULL(u.locked_tag,'N') AS locked_tag, CASE WHEN ISNULL(u.disable_time,'')='' THEN 'none' WHEN LEFT(u.disable_time,10)<='2026-10-14' THEN 'disabled' ELSE 'future' END AS disable_state, CASE WHEN ISNULL(u.able_time,'')='' THEN 'none' WHEN LEFT(u.able_time,10)<='2026-10-14' THEN 'enabled' ELSE 'notyet' END AS able_state, ISNULL(u.authen_type,'') AS authen_type, CASE WHEN EXISTS (SELECT 1 FROM u8cloud.dbo.sm_user_role ur WHERE ur.cuserid=u.cuserid AND ISNULL(ur.dr,0)=0) THEN 'Y' ELSE 'N' END AS has_role, COUNT(*) AS user_cnt FROM u8cloud.dbo.sm_user u WHERE ISNULL(u.dr,0)=0 GROUP BY CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END, ISNULL(u.locked_tag,'N'), CASE WHEN ISNULL(u.disable_time,'')='' THEN 'none' WHEN LEFT(u.disable_time,10)<='2026-10-14' THEN 'disabled' ELSE 'future' END, CASE WHEN ISNULL(u.able_time,'')='' THEN 'none' WHEN LEFT(u.able_time,10)<='2026-10-14' THEN 'enabled' ELSE 'notyet' END, ISNULL(u.authen_type,''), CASE WHEN EXISTS (SELECT 1 FROM u8cloud.dbo.sm_user_role ur WHERE ur.cuserid=u.cuserid AND ISNULL(ur.dr,0)=0) THEN 'Y' ELSE 'N' END ORDER BY 1, 2, 3, 4
##QZ_f1_sod
SELECT ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) AS pk_system, CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END AS prep_kind, COUNT(*) AS vch_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS checked_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS posted_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS casher_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_check, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_post, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') THEN 1 ELSE 0 END) AS check_eq_post, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_casher, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')) AS prep_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A')) AS check_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A')) AS post_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A')) AS casher_n FROM u8cloud_QZ.dbo.gl_voucher v JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook LEFT JOIN u8cloud_QZ.dbo.sm_user u ON u.cuserid=v.pk_prepared WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, UPPER(RTRIM(v.pk_system)), CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END ORDER BY 1, 2, 3
