SELECT ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) AS pk_system, CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END AS prep_kind, COUNT(*) AS vch_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS checked_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS posted_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A') IS NOT NULL THEN 1 ELSE 0 END) AS casher_cnt, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_check, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_post, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') THEN 1 ELSE 0 END) AS check_eq_post, SUM(CASE WHEN NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')=NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A') THEN 1 ELSE 0 END) AS prep_eq_casher, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A')) AS prep_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A')) AS check_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A')) AS post_n, COUNT(DISTINCT NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A')) AS casher_n FROM u8cloud.dbo.gl_voucher v JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook LEFT JOIN u8cloud.dbo.sm_user u ON u.cuserid=v.pk_prepared WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, UPPER(RTRIM(v.pk_system)), CASE WHEN u.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END ORDER BY 1, 2, 3
##QZ_f2_sod_role_combo
WITH r AS ( SELECT v.pk_glorgbook, NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A') AS uid, 'P' AS rl FROM u8cloud_QZ.dbo.gl_voucher v WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND NULLIF(NULLIF(RTRIM(v.pk_prepared),''),'N/A') IS NOT NULL UNION ALL SELECT v.pk_glorgbook, NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A'), 'C' FROM u8cloud_QZ.dbo.gl_voucher v WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND NULLIF(NULLIF(RTRIM(v.pk_checked),''),'N/A') IS NOT NULL UNION ALL SELECT v.pk_glorgbook, NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A'), 'T' FROM u8cloud_QZ.dbo.gl_voucher v WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND NULLIF(NULLIF(RTRIM(v.pk_manager),''),'N/A') IS NOT NULL UNION ALL SELECT v.pk_glorgbook, NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A'), 'K' FROM u8cloud_QZ.dbo.gl_voucher v WHERE v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND NULLIF(NULLIF(RTRIM(v.pk_casher),''),'N/A') IS NOT NULL), u AS (SELECT pk_glorgbook, uid, MAX(CASE WHEN rl='P' THEN 1 ELSE 0 END) AS p, MAX(CASE WHEN rl='C' THEN 1 ELSE 0 END) AS c, MAX(CASE WHEN rl='T' THEN 1 ELSE 0 END) AS t, MAX(CASE WHEN rl='K' THEN 1 ELSE 0 END) AS k FROM r GROUP BY pk_glorgbook, uid) SELECT ob.glorgbookcode, CASE WHEN su.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END AS sys_account, CASE WHEN u.p=1 THEN 'P' ELSE '-' END + CASE WHEN u.c=1 THEN 'C' ELSE '-' END + CASE WHEN u.t=1 THEN 'T' ELSE '-' END + CASE WHEN u.k=1 THEN 'K' ELSE '-' END AS pattern, COUNT(*) AS user_cnt FROM u JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=u.pk_glorgbook LEFT JOIN u8cloud_QZ.dbo.sm_user su ON su.cuserid=u.uid WHERE ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, CASE WHEN su.user_code='tbadmin' THEN 'tbadmin' ELSE 'other' END, CASE WHEN u.p=1 THEN 'P' ELSE '-' END + CASE WHEN u.c=1 THEN 'C' ELSE '-' END + CASE WHEN u.t=1 THEN 'T' ELSE '-' END + CASE WHEN u.k=1 THEN 'K' ELSE '-' END ORDER BY 1, 2, 3
##SF_f2_sod_role_combo
