CASE WHEN u.c=1 THEN 'C' ELSE '-' END + CASE WHEN u.t=1 THEN 'T' ELSE '-' END + CASE WHEN u.k=1 THEN 'K' ELSE '-' END ORDER BY 1, 2, 3
