##QZ_g3_cash_tagged
SELECT ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) AS pk_system, COUNT(*) AS cash_line_cnt, SUM(CASE WHEN EXISTS (SELECT 1 FROM u8cloud_QZ.dbo.gl_cashflowcase cf WHERE cf.pk_detail=d.pk_detail AND ISNULL(cf.dr,0)=0) THEN 1 ELSE 0 END) AS tagged_line_cnt FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud_QZ.dbo.bd_accsubj a ON a.pk_accsubj=d.pk_accsubj JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND a.cashbankflag IS NOT NULL AND a.cashbankflag<>0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) ORDER BY 1, 2
##SF_g3_cash_tagged
SELECT ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) AS pk_system, COUNT(*) AS cash_line_cnt, SUM(CASE WHEN EXISTS (SELECT 1 FROM u8cloud.dbo.gl_cashflowcase cf WHERE cf.pk_detail=d.pk_detail AND ISNULL(cf.dr,0)=0) THEN 1 ELSE 0 END) AS tagged_line_cnt FROM u8cloud.dbo.gl_detail d JOIN u8cloud.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher JOIN u8cloud.dbo.bd_accsubj a ON a.pk_accsubj=d.pk_accsubj JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=v.pk_glorgbook WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND v.year+v.period BETWEEN '202510' AND '202609' AND a.cashbankflag IS NOT NULL AND a.cashbankflag<>0 AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1006-0001','1007-0001') GROUP BY ob.glorgbookcode, UPPER(RTRIM(v.pk_system)) ORDER BY 1, 2
