SELECT s.pk_corp, c.unitcode, s.initcode, s.initname, LEFT(s.value,80) AS value FROM u8cloud_QZ.dbo.pub_sysinit s LEFT JOIN u8cloud_QZ.dbo.bd_corp c ON c.pk_corp=s.pk_corp WHERE ISNULL(s.dr,0)=0 AND (LEFT(s.initcode,2)='GL' OR s.initname LIKE N'%总账%' OR s.initname LIKE N'%凭证%' OR s.initname LIKE N'%记账%' OR s.initname LIKE N'%结账%' OR s.initname LIKE N'%科目%' OR s.initname LIKE N'%现金流量%' OR s.initname LIKE N'%核销%' OR s.initname LIKE N'%出纳%' OR s.initname LIKE N'%账簿%') AND UPPER(s.initcode) NOT LIKE '%PWD%' AND UPPER(s.initcode) NOT LIKE '%PASS%' AND ISNULL(s.initname,'') NOT LIKE N'%密码%' ORDER BY s.initcode, c.unitcode
##SF_g8_sysinit_gl cap=30000
SELECT s.pk_corp, c.unitcode, s.initcode, s.initname, LEFT(s.value,80) AS value FROM u8cloud.dbo.pub_sysinit s LEFT JOIN u8cloud.dbo.bd_corp c ON c.pk_corp=s.pk_corp WHERE ISNULL(s.dr,0)=0 AND (LEFT(s.initcode,2)='GL' OR s.initname LIKE N'%总账%' OR s.initname LIKE N'%凭证%' OR s.initname LIKE N'%记账%' OR s.initname LIKE N'%结账%' OR s.initname LIKE N'%科目%' OR s.initname LIKE N'%现金流量%' OR s.initname LIKE N'%核销%' OR s.initname LIKE N'%出纳%' OR s.initname LIKE N'%账簿%') AND UPPER(s.initcode) NOT LIKE '%PWD%' AND UPPER(s.initcode) NOT LIKE '%PASS%' AND ISNULL(s.initname,'') NOT LIKE N'%密码%' ORDER BY s.initcode, c.unitcode
##QZ_g9_xlog_suspicious
SELECT p.pat, COUNT(*) AS cnt, MIN(x.doc_time) AS min_doc_time, MAX(x.doc_time) AS max_doc_time FROM u8cloud_QZ.dbo.xx_xlog x CROSS APPLY (VALUES ('quote', CASE WHEN x.doc_source LIKE '%''%' OR x.doc_destination LIKE '%''%' THEN 1 ELSE 0 END), ('waitfor', CASE WHEN x.doc_source LIKE '%WAITFOR%' OR x.doc_destination LIKE '%WAITFOR%' THEN 1 ELSE 0 END), ('or_1_eq_1', CASE WHEN x.doc_source LIKE '%OR ''1''=''1%' OR x.doc_destination LIKE '%OR ''1''=''1%' THEN 1 ELSE 0 END), ('is_srvrolemember', CASE WHEN x.doc_source LIKE '%IS_SRVROLEMEMBER%' OR x.doc_destination LIKE '%IS_SRVROLEMEMBER%' THEN 1 ELSE 0 END), ('host_name', CASE WHEN x.doc_source LIKE '%HOST_NAME%' OR x.doc_destination LIKE '%HOST_NAME%' THEN 1 ELSE 0 END)) AS p(pat, hit) WHERE p.hit=1 GROUP BY p.pat ORDER BY 1
##SF_g9_xlog_suspicious
SELECT p.pat, COUNT(*) AS cnt, MIN(x.doc_time) AS min_doc_time, MAX(x.doc_time) AS max_doc_time FROM u8cloud.dbo.xx_xlog x CROSS APPLY (VALUES ('quote', CASE WHEN x.doc_source LIKE '%''%' OR x.doc_destination LIKE '%''%' THEN 1 ELSE 0 END), ('waitfor', CASE WHEN x.doc_source LIKE '%WAITFOR%' OR x.doc_destination LIKE '%WAITFOR%' THEN 1 ELSE 0 END), ('or_1_eq_1', CASE WHEN x.doc_source LIKE '%OR ''1''=''1%' OR x.doc_destination LIKE '%OR ''1''=''1%' THEN 1 ELSE 0 END), ('is_srvrolemember', CASE WHEN x.doc_source LIKE '%IS_SRVROLEMEMBER%' OR x.doc_destination LIKE '%IS_SRVROLEMEMBER%' THEN 1 ELSE 0 END), ('host_name', CASE WHEN x.doc_source LIKE '%HOST_NAME%' OR x.doc_destination LIKE '%HOST_NAME%' THEN 1 ELSE 0 END)) AS p(pat, hit) WHERE p.hit=1 GROUP BY p.pat ORDER BY 1
