##QZ_balance_gl cap=100000
WITH st AS (SELECT s.pk_glorgbook, ob.glorgbookcode, CAST(s.settledyear AS INT) AS y, CAST(s.settledperiod AS INT) AS p FROM u8cloud_QZ.dbo.gl_syssettled s JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=s.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND s.funccode='2002' AND LTRIM(RTRIM(ISNULL(s.settledyear,'')))<>'' AND LTRIM(RTRIM(ISNULL(s.settledperiod,'')))<>''), per0 AS (SELECT pk_glorgbook, glorgbookcode, y, p, 1 AS rk FROM st UNION ALL SELECT pk_glorgbook, glorgbookcode, CASE WHEN p=1 THEN y-1 ELSE y END, CASE WHEN p=1 THEN 12 ELSE p-1 END, 2 FROM st), per AS (SELECT pk_glorgbook, glorgbookcode, rk, RIGHT('0000'+CAST(y AS VARCHAR(4)),4) AS yy, RIGHT('0'+CAST(p AS VARCHAR(2)),2) AS pp FROM per0), bal AS (SELECT b.pk_glorgbook, b.year AS y, b.period AS p, b.pk_accsubj, b.assid, b.pk_currtype, SUM(b.localdebitamount) AS d, SUM(b.localcreditamount) AS c, SUM(b.debitamount) AS od, SUM(b.creditamount) AS oc FROM u8cloud_QZ.dbo.gl_balance b WHERE ISNULL(b.dr,0)=0 GROUP BY b.pk_glorgbook, b.year, b.period, b.pk_accsubj, b.assid, b.pk_currtype), agg AS (SELECT per.glorgbookcode, per.rk, per.yy, per.pp, x.pk_accsubj, x.assid, x.pk_currtype, SUM(CASE WHEN x.p='00' THEN x.d-x.c ELSE 0 END) AS yr_open_net, SUM(CASE WHEN x.p=per.pp THEN x.d ELSE 0 END) AS cur_d, SUM(CASE WHEN x.p=per.pp THEN x.c ELSE 0 END) AS cur_c, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.d ELSE 0 END) AS ytd_d, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.c ELSE 0 END) AS ytd_c, SUM(CASE WHEN x.p='00' THEN x.od-x.oc ELSE 0 END) AS o_yr_open_net, SUM(CASE WHEN x.p=per.pp THEN x.od ELSE 0 END) AS o_cur_d, SUM(CASE WHEN x.p=per.pp THEN x.oc ELSE 0 END) AS o_cur_c, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.od ELSE 0 END) AS o_ytd_d, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.oc ELSE 0 END) AS o_ytd_c FROM per JOIN bal x ON x.pk_glorgbook=per.pk_glorgbook AND x.y=per.yy GROUP BY per.glorgbookcode, per.rk, per.yy, per.pp, x.pk_accsubj, x.assid, x.pk_currtype) SELECT g.glorgbookcode, g.rk, g.yy, g.pp, a.subjcode, a.endflag, g.pk_currtype, g.assid, STUFF((SELECT '|'+ISNULL(i.bdname,'?')+':'+ISNULL(f.valuecode,'') FROM u8cloud_QZ.dbo.gl_freevalue f JOIN u8cloud_QZ.dbo.bd_bdinfo i ON i.pk_bdinfo=f.checktype WHERE f.freevalueid=g.assid AND ISNULL(f.dr,0)=0 ORDER BY f.assindex FOR XML PATH(''),TYPE).value('(./text())[1]','nvarchar(max)'),1,1,'') AS dims, g.yr_open_net+(g.ytd_d-g.cur_d)-(g.ytd_c-g.cur_c) AS open_net, g.cur_d AS cur_debit, g.cur_c AS cur_credit, g.ytd_d AS ytd_debit, g.ytd_c AS ytd_credit, g.yr_open_net+g.ytd_d-g.ytd_c AS close_net, g.yr_open_net AS yr_open_net, g.o_yr_open_net+(g.o_ytd_d-g.o_cur_d)-(g.o_ytd_c-g.o_cur_c) AS orig_open_net, g.o_cur_d AS orig_cur_debit, g.o_cur_c AS orig_cur_credit, g.o_ytd_d AS orig_ytd_debit, g.o_ytd_c AS orig_ytd_credit, g.o_yr_open_net+g.o_ytd_d-g.o_ytd_c AS orig_close_net FROM agg g JOIN u8cloud_QZ.dbo.bd_accsubj a ON a.pk_accsubj=g.pk_accsubj WHERE g.yr_open_net<>0 OR g.cur_d<>0 OR g.cur_c<>0 OR g.ytd_d<>0 OR g.ytd_c<>0 ORDER BY g.glorgbookcode, g.rk, a.subjcode, g.assid
##SF_balance_gl cap=100000
WITH st AS (SELECT s.pk_glorgbook, ob.glorgbookcode, CAST(s.settledyear AS INT) AS y, CAST(s.settledperiod AS INT) AS p FROM u8cloud.dbo.gl_syssettled s JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=s.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND s.funccode='2002' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1004-0001','1007-0001') AND LTRIM(RTRIM(ISNULL(s.settledyear,'')))<>'' AND LTRIM(RTRIM(ISNULL(s.settledperiod,'')))<>''), per0 AS (SELECT pk_glorgbook, glorgbookcode, y, p, 1 AS rk FROM st UNION ALL SELECT pk_glorgbook, glorgbookcode, CASE WHEN p=1 THEN y-1 ELSE y END, CASE WHEN p=1 THEN 12 ELSE p-1 END, 2 FROM st), per AS (SELECT pk_glorgbook, glorgbookcode, rk, RIGHT('0000'+CAST(y AS VARCHAR(4)),4) AS yy, RIGHT('0'+CAST(p AS VARCHAR(2)),2) AS pp FROM per0), bal AS (SELECT b.pk_glorgbook, b.year AS y, b.period AS p, b.pk_accsubj, b.assid, b.pk_currtype, SUM(b.localdebitamount) AS d, SUM(b.localcreditamount) AS c, SUM(b.debitamount) AS od, SUM(b.creditamount) AS oc FROM u8cloud.dbo.gl_balance b WHERE ISNULL(b.dr,0)=0 GROUP BY b.pk_glorgbook, b.year, b.period, b.pk_accsubj, b.assid, b.pk_currtype), agg AS (SELECT per.glorgbookcode, per.rk, per.yy, per.pp, x.pk_accsubj, x.assid, x.pk_currtype, SUM(CASE WHEN x.p='00' THEN x.d-x.c ELSE 0 END) AS yr_open_net, SUM(CASE WHEN x.p=per.pp THEN x.d ELSE 0 END) AS cur_d, SUM(CASE WHEN x.p=per.pp THEN x.c ELSE 0 END) AS cur_c, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.d ELSE 0 END) AS ytd_d, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.c ELSE 0 END) AS ytd_c, SUM(CASE WHEN x.p='00' THEN x.od-x.oc ELSE 0 END) AS o_yr_open_net, SUM(CASE WHEN x.p=per.pp THEN x.od ELSE 0 END) AS o_cur_d, SUM(CASE WHEN x.p=per.pp THEN x.oc ELSE 0 END) AS o_cur_c, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.od ELSE 0 END) AS o_ytd_d, SUM(CASE WHEN x.p>='01' AND x.p<=per.pp THEN x.oc ELSE 0 END) AS o_ytd_c FROM per JOIN bal x ON x.pk_glorgbook=per.pk_glorgbook AND x.y=per.yy GROUP BY per.glorgbookcode, per.rk, per.yy, per.pp, x.pk_accsubj, x.assid, x.pk_currtype) SELECT g.glorgbookcode, g.rk, g.yy, g.pp, a.subjcode, a.endflag, g.pk_currtype, g.assid, STUFF((SELECT '|'+ISNULL(i.bdname,'?')+':'+ISNULL(f.valuecode,'') FROM u8cloud.dbo.gl_freevalue f JOIN u8cloud.dbo.bd_bdinfo i ON i.pk_bdinfo=f.checktype WHERE f.freevalueid=g.assid AND ISNULL(f.dr,0)=0 ORDER BY f.assindex FOR XML PATH(''),TYPE).value('(./text())[1]','nvarchar(max)'),1,1,'') AS dims, g.yr_open_net+(g.ytd_d-g.cur_d)-(g.ytd_c-g.cur_c) AS open_net, g.cur_d AS cur_debit, g.cur_c AS cur_credit, g.ytd_d AS ytd_debit, g.ytd_c AS ytd_credit, g.yr_open_net+g.ytd_d-g.ytd_c AS close_net, g.yr_open_net AS yr_open_net, g.o_yr_open_net+(g.o_ytd_d-g.o_cur_d)-(g.o_ytd_c-g.o_cur_c) AS orig_open_net, g.o_cur_d AS orig_cur_debit, g.o_cur_c AS orig_cur_credit, g.o_ytd_d AS orig_ytd_debit, g.o_ytd_c AS orig_ytd_credit, g.o_yr_open_net+g.o_ytd_d-g.o_ytd_c AS orig_close_net FROM agg g JOIN u8cloud.dbo.bd_accsubj a ON a.pk_accsubj=g.pk_accsubj WHERE g.yr_open_net<>0 OR g.cur_d<>0 OR g.cur_c<>0 OR g.ytd_d<>0 OR g.ytd_c<>0 ORDER BY g.glorgbookcode, g.rk, a.subjcode, g.assid
