WITH st AS (SELECT s.pk_glorgbook, ob.glorgbookcode, CAST(s.settledyear AS INT) AS y, CAST(s.settledperiod AS INT) AS p FROM u8cloud_QZ.dbo.gl_syssettled s JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.pk_glorgbook=s.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND s.funccode='2002' AND LTRIM(RTRIM(ISNULL(s.settledyear,'')))<>'' AND LTRIM(RTRIM(ISNULL(s.settledperiod,'')))<>''), per0 AS (SELECT pk_glorgbook, glorgbookcode, y, p, 1 AS rk FROM st UNION ALL SELECT pk_glorgbook, glorgbookcode, CASE WHEN p=1 THEN y-1 ELSE y END, CASE WHEN p=1 THEN 12 ELSE p-1 END, 2 FROM st), per AS (SELECT pk_glorgbook, glorgbookcode, rk, RIGHT('0000'+CAST(y AS VARCHAR(4)),4) AS yy, RIGHT('0'+CAST(p AS VARCHAR(2)),2) AS pp FROM per0), mth AS (SELECT v.pk_glorgbook, v.year+v.period AS ym, v.year AS y, d.pk_accsubj, d.assid, d.pk_currtype, SUM(d.localdebitamount) AS d, SUM(d.localcreditamount) AS c, COUNT(*) AS n FROM u8cloud_QZ.dbo.gl_detail d JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_voucher=d.pk_voucher WHERE d.dr=0 AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND ISNULL(v.pk_manager,'') NOT IN ('','N/A') GROUP BY v.pk_glorgbook, v.year+v.period, v.year, d.pk_accsubj, d.assid, d.pk_currtype) SELECT per.glorgbookcode, per.rk, per.yy, per.pp, a.subjcode, a.endflag, m.pk_currtype, m.assid, STUFF((SELECT '|'+ISNULL(i.bdname,'?')+':'+ISNULL(f.valuecode,'') FROM u8cloud_QZ.dbo.gl_freevalue f JOIN u8cloud_QZ.dbo.bd_bdinfo i ON i.pk_bdinfo=f.checktype WHERE f.freevalueid=m.assid AND ISNULL(f.dr,0)=0 ORDER BY f.assindex FOR XML PATH(''),TYPE).value('(./text())[1]','nvarchar(max)'),1,1,'') AS dims, SUM(CASE WHEN m.ym=per.yy+per.pp THEN m.d ELSE 0 END) AS cur_debit, SUM(CASE WHEN m.ym=per.yy+per.pp THEN m.c ELSE 0 END) AS cur_credit, SUM(CASE WHEN m.y=per.yy THEN m.d ELSE 0 END) AS ytd_debit, SUM(CASE WHEN m.y=per.yy THEN m.c ELSE 0 END) AS ytd_credit, SUM(m.d) AS cum_debit, SUM(m.c) AS cum_credit, SUM(m.n) AS vch_line_cnt FROM per JOIN mth m ON m.pk_glorgbook=per.pk_glorgbook AND m.ym<=per.yy+per.pp JOIN u8cloud_QZ.dbo.bd_accsubj a ON a.pk_accsubj=m.pk_accsubj GROUP BY per.glorgbookcode, per.rk, per.yy, per.pp, a.subjcode, a.endflag, m.pk_currtype, m.assid ORDER BY per.glorgbookcode, per.rk, a.subjcode, m.assid
