nt FROM per JOIN mth m ON m.pk_glorgbook=per.pk_glorgbook AND m.ym<=per.yy+per.pp JOIN u8cloud.dbo.bd_accsubj a ON a.pk_accsubj=m.pk_accsubj GROUP BY per.glorgbookcode, per.rk, per.yy, per.pp, a.subjcode, a.endflag, m.pk_currtype, m.assid ORDER BY per.glorgbookcode, per.rk, a.subjcode, m.assid
