WITH st AS (SELECT s.pk_glorgbook, ob.glorgbookcode, CAST(s.settledyear AS INT) AS y, CAST(s.settledperiod AS INT) AS p FROM u8cloud.dbo.gl_syssettled s JOIN u8cloud.dbo.bd_glorgbook ob ON ob.pk_glorgbook=s.pk_glorgbook WHERE ISNULL(s.dr,0)=0 AND ISNULL(ob.dr,0)=0 AND s.funccode='2002' AND ob.glorgbookcode IN ('1001-0001','1002-0001','1003-0001','1004-0001','1007-0001') AND LTRIM(RTRIM(ISNULL(s.settledyear,'')))<>'' AND LTRIM(RTRIM(ISNULL(s.settledperiod,'')))<>''), per0 AS (SELECT pk_glorgbook, glorgbookcode, y, p, 1 AS rk FROM st UNION ALL SELECT pk_glorgbook, glorgbookcode, CASE WHEN p=1 THEN y-1 ELSE y END, CASE WHEN p=1 THEN 12 ELSE p-1 END, 2 FROM st), per AS (SELECT pk_glorgbook, glorgbookcode, rk, RIGHT('0000'+CAST(y AS VARCHAR(4)),4) AS yy, RIGHT('0'+CAST(p AS VARCHAR(2)),2) AS pp FROM per0) SELECT per.glorgbookcode, per.rk, per.yy, per.pp, c.cfitemcode, MAX(c.cfitemname) AS cfitemname, ISNULL(LEFT(a1.subjcode,1),'?') AS line_first, ISNULL(LEFT(a2.subjcode,1),'?') AS opp_first, ISNULL(cf.flag,-1) AS flag, SUM(CASE WHEN v.period=per.pp THEN 1 ELSE 0 END) AS cur_rows, SUM(CASE WHEN v.period=per.pp THEN cf.money ELSE 0 END) AS cur_money, SUM(CASE WHEN v.period=per.pp THEN cf.moneymain ELSE 0 END) AS cur_moneymain, SUM(CASE WHEN v.period=per.pp THEN cf.moneyass ELSE 0 END) AS cur_moneyass, COUNT(*) AS ytd_rows, SUM(cf.money) AS ytd_money, SUM(cf.moneymain) AS ytd_moneymain, SUM(cf.moneyass) AS ytd_moneyass FROM per JOIN u8cloud.dbo.gl_voucher v ON v.pk_glorgbook=per.pk_glorgbook AND v.year=per.yy AND v.period>='01' AND v.period<=per.pp AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND ISNULL(v.pk_manager,'') NOT IN ('','N/A') JOIN u8cloud.dbo.gl_detail d ON d.pk_voucher=v.pk_voucher AND d.dr=0 JOIN u8cloud.dbo.gl_cashflowcase cf ON cf.pk_detail=d.pk_detail AND ISNULL(cf.dr,0)=0 JOIN u8cloud.dbo.bd_cashflow c ON c.pk_cashflow=cf.pk_cashflow LEFT JOIN u8cloud.dbo.bd_accsubj a1 ON a1.pk_accsubj=d.pk_accsubj LEFT JOIN u8cloud.dbo.gl_detail d2 ON d2.pk_detail=cf.pk_detail_opp LEFT JOIN u8cloud.dbo.bd_accsubj a2 ON a2.pk_accsubj=d2.pk_accsubj GROUP BY per.glorgbookcode, per.rk, per.yy, per.pp, c.cfitemcode, ISNULL(LEFT(a1.subjcode,1),'?'), ISNULL(LEFT(a2.subjcode,1),'?'), ISNULL(cf.flag,-1) ORDER BY per.glorgbookcode, per.rk, c.cfitemcode
-- ===== q11.sql（黄金基线：成本损益科目按凭证来源的发生额，结果只存本机）
##QZ_pl_by_system cap=50000
WITH per(book,yy,pp) AS (SELECT * FROM (VALUES ('1001-0001','2025','10'),('1001-0001','2025','11'),('1002-0001','2025','11'),('1002-0001','2025','12'),('1003-0001','2025','10'),('1003-0001','2025','11'),('1006-0001','2025','11'),('1006-0001','2025','12'),('1007-0001','2025','01'),('1007-0001','2025','02')) v(b,y,p)) SELECT per.book, per.yy, per.pp, a.subjcode, UPPER(RTRIM(v.pk_system)), SUM(CASE WHEN v.period=per.pp THEN d.localdebitamount ELSE 0 END), SUM(CASE WHEN v.period=per.pp THEN d.localcreditamount ELSE 0 END), SUM(d.localdebitamount), SUM(d.localcreditamount) FROM per JOIN u8cloud_QZ.dbo.bd_glorgbook ob ON ob.glorgbookcode=per.book JOIN u8cloud_QZ.dbo.gl_voucher v ON v.pk_glorgbook=ob.pk_glorgbook AND v.year=per.yy AND v.period>='01' AND v.period<=per.pp AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND ISNULL(v.pk_manager,'') NOT IN ('','N/A') JOIN u8cloud_QZ.dbo.gl_detail d ON d.pk_voucher=v.pk_voucher AND d.dr=0 JOIN u8cloud_QZ.dbo.bd_accsubj a ON a.pk_accsubj=d.pk_accsubj WHERE LEFT(a.subjcode,1) IN ('6','E','5','D') GROUP BY per.book, per.yy, per.pp, a.subjcode, UPPER(RTRIM(v.pk_system))
##SF_pl_by_system cap=50000
WITH per(book,yy,pp) AS (SELECT * FROM (VALUES ('1001-0001','2025','11'),('1001-0001','2025','12'),('1002-0001','2025','11'),('1002-0001','2025','12'),('1003-0001','2025','11'),('1003-0001','2025','12'),('1004-0001','2024','11'),('1004-0001','2024','12'),('1007-0001','2025','11'),('1007-0001','2025','12')) v(b,y,p)) SELECT per.book, per.yy, per.pp, a.subjcode, UPPER(RTRIM(v.pk_system)), SUM(CASE WHEN v.period=per.pp THEN d.localdebitamount ELSE 0 END), SUM(CASE WHEN v.period=per.pp THEN d.localcreditamount ELSE 0 END), SUM(d.localdebitamount), SUM(d.localcreditamount) FROM per JOIN u8cloud.dbo.bd_glorgbook ob ON ob.glorgbookcode=per.book JOIN u8cloud.dbo.gl_voucher v ON v.pk_glorgbook=ob.pk_glorgbook AND v.year=per.yy AND v.period>='01' AND v.period<=per.pp AND v.dr=0 AND ISNULL(v.discardflag,'N')<>'Y' AND ISNULL(v.pk_manager,'') NOT IN ('','N/A') JOIN u8cloud.dbo.gl_detail d ON d.pk_voucher=v.pk_voucher AND d.dr=0 JOIN u8cloud.dbo.bd_accsubj a ON a.pk_accsubj=d.pk_accsubj WHERE LEFT(a.subjcode,1) IN ('6','E','5','D') GROUP BY per.book, per.yy, per.pp, a.subjcode, UPPER(RTRIM(v.pk_system))
